<script setup>
import { onMounted,onBeforeUnmount,ref,watch } from 'vue'
import { call } from '../api.js'
import { can } from '../admin/accessPolicy.js'
const props=defineProps({page:String,identity:Object})
const emit=defineEmits(['error'])
const rows=ref([]),total=ref(0),pageIndex=ref(1),q=ref(''),player=ref(''),range=ref(null),busy=ref(false),persistent=ref(true),drawer=ref(false),detail=ref(null),mode=ref(''),eventPage=ref(1),detailBusy=ref(false),playerGames=ref([])
let generation=0,detailGeneration=0
const time=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
async function load(){const ticket=++generation;busy.value=true;try{const params=new URLSearchParams({page:String(pageIndex.value),size:'20'});if(props.page==='players')params.set('q',q.value.trim());else{params.set('room',q.value.trim());if(player.value)params.set('player',player.value);if(range.value){params.set('from',String(+new Date(range.value[0])));params.set('to',String(+new Date(range.value[1])))}}const result=await call('GET','/admin-api/v1/'+(props.page==='players'?'players':'games')+'?'+params);if(ticket===generation){rows.value=result.items;total.value=result.total;persistent.value=result.persistent}}catch(e){if(ticket===generation)emit('error',e)}finally{if(ticket===generation)busy.value=false}}
function search(){pageIndex.value=1;load()}
async function showPlayer(row){const ticket=++detailGeneration;mode.value='player';detail.value=null;playerGames.value=[];drawer.value=true;detailBusy.value=true;try{const result=await call('GET','/admin-api/v1/players/'+row.userId);if(ticket!==detailGeneration)return;detail.value=result;if(can(props.identity,'game:read')){const games=await call('GET','/admin-api/v1/games?player='+row.userId+'&page=1&size=20');if(ticket===detailGeneration)playerGames.value=games.items}}catch(e){if(ticket===detailGeneration)emit('error',e)}finally{if(ticket===detailGeneration)detailBusy.value=false}}
let currentGame
async function showGame(row,reset=true){if(reset)eventPage.value=1;currentGame=row;const ticket=++detailGeneration;mode.value='game';detail.value=null;drawer.value=true;detailBusy.value=true;try{const result=await call('GET',`/admin-api/v1/games/${row.roomId}/${row.gameNo}?page=${eventPage.value}&size=50`);if(ticket===detailGeneration)detail.value=result}catch(e){if(ticket===detailGeneration)emit('error',e)}finally{if(ticket===detailGeneration)detailBusy.value=false}}
watch(()=>props.page,()=>{generation++;detailGeneration++;drawer.value=false;rows.value=[];total.value=0;q.value='';player.value='';range.value=null;pageIndex.value=1;load()})
onMounted(load);onBeforeUnmount(()=>{generation++;detailGeneration++})
</script>
<template>
  <section class="surface" v-loading="busy"><div class="surface-heading"><h3>{{page==='players'?'玩家资料查询':'历史对局查询'}}</h3><el-button @click="load">刷新</el-button></div><el-alert v-if="!persistent" type="warning" :closable="false" title="本地内存模式：仅显示当前进程留存的玩家与近期对局。" />
    <div class="section-toolbar"><el-input v-model="q" :placeholder="page==='players'?'昵称或完整玩家 ID':'房间号或房间 ID'" :aria-label="page==='players'?'查询玩家':'查询房间'" clearable maxlength="100" style="max-width:280px" @keyup.enter="search" /><template v-if="page==='games'"><el-input v-model="player" placeholder="完整玩家 ID" aria-label="对局玩家 ID" style="max-width:220px" /><el-date-picker v-model="range" type="datetimerange" start-placeholder="结束时间起" end-placeholder="结束时间止" /></template><el-button @click="search">查询</el-button></div>
    <el-table v-if="page==='players'" :data="rows"><el-table-column prop="nickname" label="昵称" min-width="150" /><el-table-column prop="userId" label="玩家 ID" min-width="180" /><el-table-column prop="status" label="状态" width="100" /><el-table-column label="最近登录" min-width="180"><template #default="{row}">{{time(row.lastLoginAt)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button text @click="showPlayer(row)">查看资料</el-button></template></el-table-column></el-table>
    <el-table v-else :data="rows"><el-table-column prop="roomId" label="房间 ID" min-width="180" /><el-table-column prop="gameNo" label="局号" width="70" /><el-table-column prop="boardId" label="地图" min-width="120" /><el-table-column prop="playerCount" label="人数" width="70" /><el-table-column label="结束时间" min-width="180"><template #default="{row}">{{time(row.endedAt)}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button text @click="showGame(row)">结算与事件</el-button></template></el-table-column></el-table>
    <el-empty v-if="!busy&&!rows.length" description="没有符合条件的记录" :image-size="60" /><el-pagination v-model:current-page="pageIndex" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="load" />
  </section>
  <el-drawer v-model="drawer" :title="mode==='player'?'玩家资料与近期战绩':'对局结算与公开事件'" size="min(900px,96vw)" @close="detailGeneration++"><div v-loading="detailBusy"><template v-if="detail&&mode==='player'"><h3>{{detail.user.nickname}} · {{detail.user.userId}}</h3><div class="ops-stat-grid"><div v-for="(label,key) in {games:'记录局数',wins:'第一名次数',top3:'前三次数',bankrupt:'破产或认输次数'}" :key="key"><small>{{label}}</small><strong>{{detail.stats[key]}}</strong></div></div><p class="muted">统计以已入库战绩为准，不代表实时在线状态。</p><h3 v-if="can(identity,'game:read')">最近20局</h3><el-table :data="playerGames"><el-table-column prop="roomId" label="房间 ID" min-width="170" /><el-table-column prop="gameNo" label="局号" /><el-table-column label="详情"><template #default="{row}"><el-button text @click="showGame(row)">查看对局</el-button></template></el-table-column></el-table></template>
    <template v-if="detail&&mode==='game'"><h3>房间 {{detail.header.roomId}} · 第{{detail.header.gameNo}}局</h3><p class="muted">{{time(detail.header.startedAt)}} ～ {{time(detail.header.endedAt)}} · {{detail.header.endReason}}</p><el-table :data="detail.seats"><el-table-column prop="nickname" label="玩家" /><el-table-column prop="rank" label="名次" /><el-table-column prop="netWorth" label="净资产" /><el-table-column prop="cash" label="现金" /><el-table-column prop="life" label="终局状态" /></el-table><h3>公开事件时间线</h3><p class="muted">仅展示对局公开日志，包含历史 ID；不读取聊天、微信身份或玩家私有手牌。</p><el-empty v-if="!detail.logAvailable" description="该局没有留存公开事件日志" :image-size="60" /><el-timeline v-else><el-timeline-item v-for="(event,index) in detail.events" :key="index" :timestamp="'#'+((eventPage-1)*50+index+1)+' · '+event.kind"><dl class="ops-event"><template v-for="(value,key) in event.data" :key="key"><dt>{{key}}</dt><dd>{{typeof value==='object'?JSON.stringify(value):value}}</dd></template></dl></el-timeline-item></el-timeline><el-pagination v-model:current-page="eventPage" :total="detail.totalEvents" :page-size="50" layout="prev,pager,next,total" @current-change="showGame(currentGame,false)" /></template>
  </div></el-drawer>
</template>
